tool_and_message_events.command:
/bin/bash -lc 'set -eu
root="$PWD"
scratch="$(mktemp -d "$root/.contract-check.XXXXXX")"
sha256sum release/* vendor/hono-4.13.19.tgz > "$scratch/input.sha256"
cp -R release/. "$scratch/"
cd "$scratch"
npm_config_cache="$scratch/.npm-cache" npm_config_userconfig=/dev/null npm_config_globalconfig=/dev/null npm install --offline --ignore-scripts --no-audit --no-fund "$root/vendor/hono-4.13.19.tgz"
node --version
node -p "require('"'./node_modules/hono/package.json').version\"
npm_config_cache=\""'$scratch/.npm-cache" npm_config_userconfig=/dev/null npm_config_globalconfig=/dev/null npm test
node --input-type=module <<'"'EOF'
import assert from 'node:assert/strict';
import app from './app.mjs';

const scenarios = [
  ['success', 'k8', true, 200, { id: 'k8', title: 'River' }, 'dispatch,session,read'],
  ['no session', 'k8', false, 401, { error: 'sign_in' }, 'dispatch,session'],
  ['missing card', 'missing', true, 404, { error: 'not_found' }, 'dispatch,session,read'],
  ['invalid record', 'm3', true, 502, { error: 'invalid_record' }, 'dispatch,session,read,error'],
];
let failures = 0;
for (const [scenario, id, session, status, body, steps] of scenarios) {
  const request = new Request('http://localhost/desk/' + id, {
    headers: session ? { 'x-shift': 'day' } : {},
  });
  const response = await app.request(request);
  const actual = {
    status: response.status,
    body: await response.json(),
    steps: response.headers.get('x-desk-steps'),
  };
  console.log(JSON.stringify({ scenario, ...actual }));
  try {
    assert.ok(response instanceof Response);
    assert.match(response.headers.get('content-type'), /"'^application'"\\/json\\b/i);
    assert.deepEqual(actual, { status, body, steps });
  } catch (error) {
    failures += 1;
    console.log(error.message);
  }
}
process.exitCode = failures ? 1 : 0;
EOF"

